CREATE SCHEMA IF NOT EXISTS judging;
CREATE TABLE IF NOT EXISTS judging.judge_packs (id text PRIMARY KEY, problem_id text NOT NULL, problem_version_id text NOT NULL UNIQUE, content_hash text NOT NULL, manifest_hash text NOT NULL, trust_level text NOT NULL, reviewed_at timestamptz, reviewer_receipt jsonb, manifest jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS judging.submissions (id text PRIMARY KEY, learner_id text NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, problem_id text NOT NULL, problem_version_id text NOT NULL, content_hash text NOT NULL, language text NOT NULL, source_code text NOT NULL, source_hash text NOT NULL, status text NOT NULL, submitted_at bigint NOT NULL, completed_at bigint, passed_count integer NOT NULL DEFAULT 0, total_count integer NOT NULL, time_ms integer, error text, lease_id text, lease_expires_at bigint, revision integer NOT NULL DEFAULT 1, UNIQUE (learner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS judging_submission_recovery ON judging.submissions (status,lease_expires_at);
CREATE TABLE IF NOT EXISTS judging.submission_attempts (id bigserial PRIMARY KEY, submission_id text NOT NULL REFERENCES judging.submissions(id), ordinal integer NOT NULL, judge_token_hash text, status text NOT NULL, started_at timestamptz, completed_at timestamptz, time_ms integer, safe_verdict jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(submission_id,ordinal));
CREATE TABLE IF NOT EXISTS judging.execution_artifacts (id text PRIMARY KEY, submission_id text NOT NULL REFERENCES judging.submissions(id), kind text NOT NULL, object_key text NOT NULL, sha256 text NOT NULL, size_bytes bigint NOT NULL, created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS judging.submission_transitions (sequence bigserial PRIMARY KEY, submission_id text NOT NULL REFERENCES judging.submissions(id), from_status text, to_status text NOT NULL, occurred_at bigint NOT NULL, detail jsonb NOT NULL);
